customCSS:
.t, .history { color: #939f91; }
.join { color: #8da101; }
.part, .quit { color: #939f91; }
.kick, .error { color: #f85552; }
.notice { color: #dfa000; }
.action { color: #df69ba; }
.mode, .nick, .topic, .server { color: #35a77c; }
.highlight { color: #5c6a72; background-color: #eaedc8; border-left: 3px solid #df69ba; padding-left: 8px; }
.reply { color: #939f91; border-left: 2px solid #3a94c5; padding-left: 6px; }
.oper { color: #fdf6e3; background-color: #dfa000; }
.reactions { color: #3a94c5; background-color: #efebd4; }
.card { background-color: #efebd4; border-color: #939f91; }
.card-title { color: #3a94c5; }
.card-desc { color: #939f91; }
.daychange { color: #939f91; border-color: #efebd4; }
